import{api,get,post,put,patch}from'./api.js';
import{state,basket,money,total,subtotal}from'./store.js';
import{modules,current}from'./router.js';
import{installKeyboard}from'./keyboard.js';
import{toast}from'./toast.js';
const root=document.querySelector('#app');let searchTimer=null,unmountKeyboard=null,searchResults=[],lastView='',customerDebtCache=null,customerDebtCachePromise=null,customerSearchSequence=0;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const val=(o,...keys)=>{for(const k of keys){const v=o?.[k];if(v!==undefined&&v!==null&&v!=='')return v;}return 'Non renseigné';};
const updateBridge=()=>window.electronAPI?.update||window.electron?.update||null;
const iconPaths={terminal:'<rect x="3" y="4" width="18" height="15" rx="2"/><path d="M7 8h10M7 12h4m-4 4h10M9 22h6"/>',boxes:'<path d="m12 3 9 5-9 5-9-5 9-5Z"/><path d="m3 12 9 5 9-5M3 16l9 5 9-5"/>',truck:'<path d="M3 6h11v12H3zM14 10h4l3 3v5h-7z"/><circle cx="7.5" cy="19" r="1.5"/><circle cx="17.5" cy="19" r="1.5"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H7a4 4 0 0 0-4 4v2"/><circle cx="9.5" cy="7" r="4"/><path d="M20 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',route:'<path d="M5 20a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z"/><path d="M19 10a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z"/><path d="M5 14V9a4 4 0 0 1 4-4h7M19 10v5a4 4 0 0 1-4 4h-7"/>',chart:'<path d="M3 3v18h18"/><rect x="7" y="12" width="3" height="6" rx="1"/><rect x="13" y="8" width="3" height="10" rx="1"/><rect x="19" y="5" width="2" height="13" rx="1"/>',sliders:'<path d="M4 21v-7m0-4V3m8 18v-9m0-4V3m8 18v-5m0-4V3"/><path d="M2 14h4m4-6h4m4 8h4"/>',smartphone:'<rect x="6" y="2" width="12" height="20" rx="2"/><path d="M11 18h2"/>',sunMoon:'<path d="M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6 7 7m10 10 1.4 1.4M18.4 5.6 17 7"/><circle cx="12" cy="12" r="4"/><path d="M19 14a5 5 0 0 1-6 6 6 6 0 0 0 6-6Z"/>',settings:'<path d="M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z"/><path d="m19.4 15 .1.1 1.4 1.1-1.4 2.4-1.7-.7a8 8 0 0 1-1.7 1l-.3 1.8h-2.8l-.3-1.8a8 8 0 0 1-1.7-1l-1.7.7-1.4-2.4 1.4-1.1a8 8 0 0 1 0-2l-1.4-1.1 1.4-2.4 1.7.7a8 8 0 0 1 1.7-1l.3-1.8h2.8l.3 1.8a8 8 0 0 1 1.7 1l1.7-.7 1.4 2.4-1.4 1.1a8 8 0 0 1 0 2Z"/>',logOut:'<path d="M10 17l5-5-5-5m5 5H3"/><path d="M12 3h6a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-6"/>',pin:'<path d="m16 3 5 5-4 1-4 4 1 4-2 2-3-5-5-3 2-2 4 1 4-4 2-3Z"/><path d="m3 21 6-6"/>'};
function iconSvg(name){return '<svg class="nav-icon" viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(iconPaths[name]||iconPaths.boxes)+'</svg>';}

function statCard(label,value,index=0){const icons=['chart','boxes','users','truck','terminal','route','sliders'];return `<div class="stat"><div class="label">${esc(label.replace(/_/g,' '))}</div><div class="value">${typeof value==='number'&&/(commandes|ventes|articles|stock faible|clients|tickets|quantité)/i.test(label)?esc(value):typeof value==='number'?money(value):esc(value)}</div><span class="stat-icon tone-${index%7}">${iconSvg(icons[index%icons.length])}</span></div>`;}
const fmtDate=v=>{const raw=v?.$date?.$numberLong??v?.$date??v?.$numberLong??v;const d=new Date(raw);return Number.isNaN(d.getTime())?'Date non renseignée':d.toLocaleString('fr-FR');};
const rowsOf=d=>{if(Array.isArray(d))return d;if(!d||typeof d!=='object')return[];for(const k of ['list','rows','logs','items','records','results'])if(Array.isArray(d[k]))return d[k];if(Array.isArray(d.data))return d.data;if(d.data&&typeof d.data==='object')return rowsOf(d.data);if(d.result&&typeof d.result==='object')return rowsOf(d.result);return[];};
function categoryLabel(item){const v=item?.category_name??item?.category;return String(typeof v==='object'?(v?.name||v?.label||v?._id||v?.id||''):v||'').trim()||'Sans catégorie';}
function categoryName(item){return categoryLabel(item).toLocaleLowerCase('fr');}
function brandLabel(item){const v=item?.brand_name??item?.brandName??item?.marque??item?.brand;return String(typeof v==='object'?(v?.name||v?.label||v?.brand_name||v?._id||v?.id||''):v??item?.brandId??item?.brand_id??'').trim()||'Sans marque';}
function brandValues(item){return [item?.brand,item?.brand_name,item?.brandName,item?.marque,item?.brandId,item?.brand_id].flatMap(v=>typeof v==='object'&&v!==null?[v.name,v.label,v.brand_name,v._id,v.id]:[v]).map(v=>String(v??'').trim().toLocaleLowerCase('fr')).filter(Boolean);}
function focusSearch(){if(state.view!=='caisse'||state.drawer)return;const input=document.querySelector('#barcode-search');if(input){try{input.focus({preventScroll:true});}catch(_){input.focus();}}}
function selectedBasketLine(){const b=basket();return b.items.find(x=>String(x._id)===String(state.selectedLineId))||b.items[0]||null;}
function quantityPicker(item){if(!item){toast('Sélectionnez un article dans le panier.','warning');return;}state.selectedLineId=String(item._id);state.drawer={title:'F4 · Modifier la quantité',html:'<form id="quantity-form" class="form-grid" data-line-id="'+esc(item._id)+'"><div class="form-field full"><label>Article</label><strong>'+esc(item.name)+'</strong></div><div class="form-field full"><label>Nouvelle quantité</label><input class="field" name="quantity" type="number" min="0.001" step="0.001" value="'+Number(item.quantity)+'" required autofocus></div><div class="form-field full"><button class="btn primary">Appliquer la quantité</button></div></form>'};render();}
function pricePicker(item){if(!item){toast('Sélectionnez un article dans le panier.','warning');return;}state.selectedLineId=String(item._id);const prices=[1,2,3].map(t=>({tier:t,price:Number(item['selling_price'+(t===1?'':'_'+t)]??(t===1?item.selling_price:0))}));state.drawer={title:'F3 · Choisir le prix',html:'<div class="price-options">'+prices.map(x=>'<button type="button" class="btn price-option" data-price-tier="'+x.tier+'" '+(x.price>0?'':'disabled')+'><b>Prix '+x.tier+'</b><strong>'+money(x.price)+' DZD</strong></button>').join('')+'</div>'};render();}
function isAdminUser(){const u=state.user||{},raw=[u.role,u.usertype,u.user_type,u.type,u.role_name].map(v=>typeof v==='object'?(v.name||v.role||v.key||''):v).map(v=>String(v||'').trim().toLowerCase().replace(/[\s-]+/g,'_'));return u.is_admin===true||u.is_super_admin===true||raw.some(v=>['admin','administrator','owner','super_admin','superadmin'].includes(v));}
function visiblePrimaryModules(){if(isAdminUser())return modules.filter(x=>x.id!=='parametres');return modules.filter(x=>['caisse','clients'].includes(x.id));}
function visibleTabs(module){if(isAdminUser()||module.id!=='clients')return module.tabs.map((label,index)=>({label,index}));return [{label:module.tabs[1],index:1},{label:module.tabs[3],index:3}];}
function pageTitle(){return current(state).label;}
function layout(content){document.documentElement.dataset.theme=state.theme;const m=current(state);root.innerHTML=`<div class="shell ${state.expanded?'expanded':''} ${state.view==='caisse'&&state.tab===0?'caisse-lock':state.view==='caisse'?'caisse-scroll':'view-'+state.view}"><aside class="rail"><div class="brand"><img class="mark" src="./assets/samarinapos-mark.svg" alt="SamarinaPOS"><span class="brand-name">SamarinaPOS</span></div><nav class="nav">${visiblePrimaryModules().map(x=>`<div class="nav-group"><button class="nav-primary ${state.view===x.id?'active':''}" data-view="${x.id}" title="${esc(x.label)}"><span class="ico">${iconSvg(x.icon)}</span><span class="nav-label">${esc(x.label)}</span></button><div class="nav-subnav" ${state.view===x.id?"":"hidden"}>${visibleTabs(x).map(({label:t,index:i})=>`<button data-view="${x.id}" data-tab="${i}" class="${state.view===x.id&&state.tab===i?'active':''}" title="${esc(t)}"><span class="nav-submark"></span><span class="nav-label">${esc(t)}</span></button>`).join('')}</div></div>`).join('')}</nav><div class="rail-bottom">${isAdminUser()?'<button data-action="companion"><span class="ico">'+iconSvg('smartphone')+'</span><span class="nav-label">Compagnon Mobile</span><span class="companion-badge" id="companion-count">'+state.connectedPhones+'</span></button>':''}<button data-action="theme"><span class="ico">${iconSvg('sunMoon')}</span><span class="nav-label">${state.theme==='dark'?'Thème clair':'Thème sombre'}</span></button>${isAdminUser()?'<div class="nav-group settings-group"><button class="nav-primary '+(state.view==='parametres'?'active':'')+'" data-view="parametres"><span class="ico">'+iconSvg('settings')+'</span><span class="nav-label">Paramètres</span></button><div class="nav-subnav" '+(state.view==='parametres'?'':'hidden')+'>'+current({view:'parametres'}).tabs.map((t,i)=>'<button data-view="parametres" data-tab="'+i+'" class="'+(state.view==='parametres'&&state.tab===i?'active':'')+'" title="'+esc(t)+'"><span class="nav-submark"></span><span class="nav-label">'+esc(t)+'</span></button>').join('')+'</div></div>':''}<button data-action="logout"><span class="ico">${iconSvg('logOut')}</span><span class="nav-label">Déconnexion</span></button></div></aside><header class="topbar"><div class="crumb">${esc(m.label)} <span class="muted">/ ${esc(m.tabs[state.tab]||m.tabs[0])}</span></div><div class="top-actions"><input id="global-search" class="field" placeholder="Rechercher · Ctrl K" aria-label="Recherche globale"><span>${esc(state.user?.name||state.user?.username||state.user?.email||'Caissier')}</span><span id="clock"></span><span class="app-version">SamarinaPOS v2.0.0-rebrand.5</span></div></header><main>${content}</main></div>${state.drawer?drawerHtml():''}`;
 document.querySelector('#clock').textContent=new Date().toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});
}
function head(title,subtitle='',action=''){return `<div class="page-head"><div><h1>${esc(title)}</h1><div class="muted">${esc(subtitle)}</div></div>${action}</div>`;}
function tabbar(){return `<div class="tabs">${current(state).tabs.map((t,i)=>`<button class="tab ${i===state.tab?'active':''}" data-tab="${i}">${esc(t)}</button>`).join('')}</div>`;}
function table(data,cols){const list=rowsOf(data);if(!list.length)return '<div class="empty">Aucun résultat pour ces critères.</div>';return `<div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${esc(c.label)}</th>`).join('')}</tr></thead><tbody>${list.map(row=>`<tr data-cart-row>${cols.map(c=>`<td>${c.render?c.render(row):esc(val(row,...c.keys))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function drawerHtml(){const d=state.drawer;return `<div class="drawer-backdrop" data-action="backdrop" style="position:fixed;inset:0;display:flex;align-items:center;justify-content:center;padding:20px;background:rgba(15,23,42,.45);backdrop-filter:blur(2px);z-index:1000"><section class="drawer modal-dialog" role="dialog" aria-modal="true" aria-label="${esc(d.title)}" tabindex="-1" style="position:relative;inset:auto;transform:none;margin:auto;width:min(720px,calc(100vw - 40px));max-width:720px;max-height:calc(100vh - 40px);overflow:auto;border-radius:16px"><div class="drawer-head"><h2>${esc(d.title)}</h2><button class="modal-close" data-action="close" aria-label="Fermer">×</button></div>${d.html}</section></div>`;}
function login(){window.location.replace('/v2/login.html');}
async function checkSession(){try{const profile=await get('auth/me');state.user=profile?.user||profile;return true;}catch{state.user=null;return false;}}
async function loadProducts(q=''){const d=await get('v2/items/fast-search',{q,limit:120,page:1});return rowsOf(d);}
function addItem(item,quantity=1){const b=basket();b.coupon=null;const id=String(item._id||item.id),amount=Math.max(1,Number(quantity)||1);state.selectedLineId=id;const found=b.items.find(x=>String(x._id)===id);if(found){const available=Number(found.available_quantity);if(found.track_inventory&&!found.negative_stock&&Number.isFinite(available)&&found.quantity+amount>available){toast('Stock insuffisant pour cet article.','error');return false;}found.quantity+=amount;}else{if(item.track_inventory&&!item.negative_stock&&Number(item.available_quantity)<amount){toast('Stock insuffisant pour cet article.','error');return false;}b.items.push({...item,_id:id,quantity:amount});}render();return true;}
async function cashier(){
 const b=basket(),sum=total(),count=b.items.reduce((n,x)=>n+(Number(x.quantity)||0),0);
 state.caisseTab=state.caisseTab||'articles';
 if(state.caisseTab==='recent'&&!Array.isArray(state.caisseRecent)){try{state.caisseRecent=rowsOf(await get('sales',{limit:8,page:1})).slice(0,8);}catch(_){state.caisseRecent=[];}}
 const tabs=[['articles','M3 3h8v8H3z M13 3h8v5h-8z M13 10h8v11h-8z M3 13h8v8H3z','Articles'],['categories','M4 4h16v16H4z M4 9h16 M9 9v11','Catégories'],['brands','M20 13 11 22 2 13V4h9z M7 9h.01','Marque'],['recent','M3 12a9 9 0 1 0 3-6.7L3 8 M3 3v5h5 M12 7v5l3 2','Ventes récentes']];
 const basketTabs=state.baskets.map(x=>'<div class="basket-tab-wrap"><button class="basket-tab '+(x.id===state.activeBasket?'active':'')+'" data-basket="'+x.id+'" aria-pressed="'+(x.id===state.activeBasket)+'"><span>'+esc(x.customer?.name||'Client de passage')+'</span><span class="basket-count">'+x.items.reduce((n,line)=>n+(Number(line.quantity)||0),0)+'</span></button>'+(state.baskets.length>1?'<button class="basket-close" data-close-basket="'+x.id+'" aria-label="Fermer le panier">×</button>':'')+'</div>').join('');
 const keys=[['F1','Rapide','amber','M7 3 3 14h7l-1 7 12-13h-7l1-5z'],['F2','Encaisser','emerald','M3 7h18v12H3z M3 10h18 M7 15h4'],['F3','Prix','violet','M20 13 11 22 2 13V4h9z M7 9h.01'],['F4','Qté','cyan','M7 4v16 M17 4v16 M3 9h18 M3 15h18'],['F5','Client','cobalt','M16 21v-2a4 4 0 0 0-4-4H7a4 4 0 0 0-4 4v2 M9.5 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M20 8v6 M17 11h6'],['F6','Versement','emerald','M12 2v20 M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6'],['F7','Livraison ZR','orange','M3 6h11v12H3z M14 10h4l3 3v5h-7z M7 21a2 2 0 1 0 0-4 2 2 0 0 0 0 4 M17 21a2 2 0 1 0 0-4 2 2 0 0 0 0 4'],['F8','Ticket','rose','M20 7h-9a4 4 0 0 0-4 4v2 M4 9l3-3 3 3 M4 17h9a4 4 0 0 0 4-4v-2 M20 15l-3 3-3-3']];
 const fkeys=keys.map(([key,label,tone,path])=>'<button class="fkey '+tone+'" data-action="'+key+'" title="'+key+' · '+label+'"><kbd>'+key+'</kbd><span class="fkey-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="'+path+'"/></svg></span><span class="fkey-label">'+label+'</span></button>').join('');
 const rows=b.items.map(r=>'<tr data-cart-line="'+esc(r._id)+'" data-cart-row class="'+(String(state.selectedLineId||'')===String(r._id)?'selected':'')+'" aria-selected="'+(String(state.selectedLineId||'')===String(r._id))+'"><td><strong>'+esc(r.name)+'</strong><small class="line-sku">'+esc(r.itemid||r.barcode_id||'')+'</small></td><td><div class="qty-control"><button class="qty-btn" data-qty="-1" data-id="'+esc(r._id)+'" aria-label="Diminuer"><svg viewBox="0 0 20 20"><path d="M4 10h12"/></svg></button><b>'+Number(r.quantity||0)+'</b><button class="qty-btn" data-qty="1" data-id="'+esc(r._id)+'" aria-label="Augmenter"><svg viewBox="0 0 20 20"><path d="M10 4v12M4 10h12"/></svg></button></div></td><td>'+money(r.selling_price)+' DZD</td><td>'+money(r.discount_amount||r.discount||0)+' DZD</td><td>'+money(Math.max(0,(Number(r.selling_price)||0)*(Number(r.quantity)||0)-(Number(r.discount_amount||r.discount)||0)))+' DZD</td><td><button class="row-action" data-edit-quantity="'+esc(r._id)+'" title="Modifier quantité"><svg viewBox="0 0 20 20"><path d="m3 14 9-9 3 3-9 9H3zM11 6l3 3"/></svg></button><button class="row-action danger" data-remove="'+esc(r._id)+'" title="Supprimer"><svg viewBox="0 0 20 20"><path d="m5 5 10 10M15 5 5 15"/></svg></button></td></tr>').join('');
 const tabHtml=tabs.map(([id,path,label])=>'<button class="catalogue-tab '+(state.caisseTab===id?'active':'')+'" data-caisse-tab="'+id+'"><span class="catalogue-icon"><svg viewBox="0 0 24 24"><path d="'+path+'"/></svg></span>'+label+'</button>').join('');
 const debt=Number(b.customer?.debt??b.customer?.balance??b.customer?.outstanding??0),tier=Number(b.customer?.price_tier||1);
 return '<div class="caisse-screen"><div class="caisse-top cashier-header-row" role="region" aria-label="Raccourcis, client et total"><section class="panel caisse-keys cashier-shortcuts"><div class="basket-strip"><div class="basket-tabs">'+basketTabs+'</div><button class="btn new-sale" data-action="new-basket">＋ Nouvelle vente</button><span class="small muted" id="mobile-sync-status">'+esc(state.mobileSync)+'</span></div><div class="fkey-grid">'+fkeys+'</div></section><section class="panel caisse-customer cashier-customer-card"><div class="customer-info"><span class="vendor-active-pill">Vendeur : '+esc(state.activeVendor?.name||'À confirmer')+'</span><strong>'+esc(b.customer?.name||'Client de passage')+'</strong>'+(b.customer?.phone?'<small>'+esc(b.customer.phone)+'</small>':'')+'</div><button class="customer-debt '+(debt>0?'due':'clear')+'" data-action="customer-debts" '+(b.customer?'':'disabled')+'>Crédit : '+money(debt)+' DZD</button></section><section class="caisse-total cashier-total-card" aria-live="polite"><span>TOTAL À PAYER</span><strong>'+money(sum)+' <small>DZD</small></strong><span class="total-meta">'+count+' article(s) · '+b.items.length+' ligne(s)</span></section></div><div class="caisse-workspace"><section class="panel cart-workspace"><div class="section-head"><h3>Panier actif</h3><span class="muted small">'+count+' article(s) · '+b.items.length+' ligne(s)</span></div><div class="cart-table-scroll">'+(b.items.length?'<div class="table-wrap"><table><thead><tr><th>Articles</th><th>Qté</th><th>Prix</th><th>Rem.</th><th>Total</th><th>Actions</th></tr></thead><tbody>'+rows+'</tbody></table></div>':'<div class="empty">Scannez un code-barres ou choisissez un article pour commencer.</div>')+'</div><div class="cart-footer"><div class="coupon-control"><input class="field" id="sale-coupon-code" placeholder="CODE DU COUPON" value="'+esc(b.coupon?.code||'')+'" autocomplete="off"><button class="btn coupon-apply" data-action="apply-coupon">Appliquer</button></div><span class="cart-line-count">'+count+' articles · '+b.items.length+' lignes</span><span class="muted small">Remise : <b>'+money(b.discount||0)+' DZD</b></span><button class="btn" data-action="sale-note">Note de vente</button><button class="btn" data-action="discount">＋ Ajouter une remise</button><button class="btn danger" data-action="clear-basket" '+(b.items.length?'':'disabled')+'>Clear</button></div><div class="cart-total-line"><span>Sous-total à payer</span><strong>'+money(sum)+' DZD</strong></div></section><aside class="panel products-workspace"><div class="toolbar"><input id="barcode-search" class="field search" placeholder="Scanner ou rechercher un article / SKU / code-barres" autocomplete="off" autofocus><button class="btn quick-add" data-action="quick-add" title="Vente rapide · saisir un prix"><svg viewBox="0 0 24 24"><path d="M12 2v20M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg><span>Prix</span></button></div><div class="catalogue-tabs">'+tabHtml+'</div><div id="product-results" class="quick-grid"></div></aside></div></div>';
}
function articleMetrics(data){const r=rowsOf(data),sum=f=>r.reduce((n,x)=>n+(Number(f(x))||0),0),stock=sum(x=>x.available_quantity),weighted=f=>sum(x=>(Number(f(x))||0)*(Number(x.available_quantity)||0));const metrics=[{label:'Achat',one:sum(x=>x.company_price||x.purchase_cost_dzd),two:weighted(x=>x.company_price||x.purchase_cost_dzd)},{label:'Vente 1',one:sum(x=>x.selling_price),two:weighted(x=>x.selling_price)},{label:'Vente 2',one:sum(x=>x.selling_price_2),two:weighted(x=>x.selling_price_2)},{label:'Vente 3',one:sum(x=>x.selling_price_3),two:weighted(x=>x.selling_price_3)}];return '<div class="article-summary-grid"><div class="article-summary-cell"></div><div class="article-summary-cell"><strong>'+r.length+' article(s) filtré(s)</strong></div><div class="article-summary-cell"></div><div class="article-summary-cell"><strong>'+money(stock)+'</strong><small>unités en stock</small></div>'+metrics.map(x=>'<div class="article-summary-cell"><div class="summary-total-one"><small>TOTAL 1 · '+x.label+'</small><strong>'+money(x.one)+' DZD</strong></div><div class="summary-total-two"><small>TOTAL 2 · '+x.label+' × stock</small><strong>'+money(x.two)+' DZD</strong></div></div>').join('')+'</div>';}

function salePaymentAmount(sale, pattern){
 const breakdown=sale.multi_payment||sale.payment_details||sale.payment_breakdown||{};
 let found=0,hasBreakdown=false;
 if(Array.isArray(breakdown)){for(const row of breakdown){const method=String(row.method||row.payment_mode||row.type||'');if(method){hasBreakdown=true;if(pattern.test(method))found+=Number(row.amount||row.paid||row.total||0);}}}
 else if(breakdown&&typeof breakdown==='object'){for(const [method,value] of Object.entries(breakdown)){hasBreakdown=true;if(pattern.test(method))found+=Number(typeof value==='object'?(value.amount||value.paid||value.total||0):value)||0;}}
 if(hasBreakdown)return found;
 return pattern.test(String(sale.payment_mode||sale.payment_method||''))?Number(sale.sales_total||sale.total||0):0;
}
