async function compressItemPhoto(file){if(!file)return '';if(file.size>5*1024*1024)throw new Error('La photo doit faire moins de 5 Mo.');const raw=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});const img=await new Promise((resolve,reject)=>{const x=new Image();x.onload=()=>resolve(x);x.onerror=reject;x.src=raw;});const scale=Math.min(1,1200/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.82);}
async function openDebtSettlement(){const customer=basket().customer;if(!customer?._id){toast('Sélectionnez un client enregistré.','warning');openCustomer();return;}const response=await get('credit/ledger/'+encodeURIComponent(customer._id));const ledger=rowsOf(response).filter(row=>Number(row.pending)>0);const due=Math.round(ledger.reduce((sum,row)=>sum+Number(row.pending||0),0)*100)/100;if(due<=0)throw new Error('Ce client ne présente aucune dette à encaisser.');state.debtSettlementContext={customerId:String(customer._id),customerName:customer.name||'Client',due};state.drawer={title:'Règlement des dettes · '+esc(customer.name||'Client'),html:'<div class="debt-settlement-summary"><span>Client</span><strong>'+esc(customer.name||'Client')+'</strong><span>Dette restante</span><strong>'+money(due)+' DZD</strong></div><div class="table-wrap debt-ledger-preview"><table><thead><tr><th>Ticket d’origine</th><th>Date</th><th>Reste dû</th></tr></thead><tbody>'+ledger.map(row=>'<tr><td>'+esc(row.receipt_number||row.sale_id||'—')+'</td><td>'+esc(fmtDate(row.date))+'</td><td>'+money(row.pending)+' DZD</td></tr>').join('')+'</tbody></table></div><form id="debt-settlement-form" class="form-grid" data-customer-id="'+esc(customer._id)+'" data-due="'+due+'"><div class="form-field"><label>Montant encaissé (DZD)</label><input class="field" name="amount" type="number" min="0.01" max="'+due+'" step=".01" required autofocus></div><div class="form-field"><label>Mode de paiement</label><select class="field" name="method"><option value="cash">DZD Cash</option><option value="tpe">DZD TPE</option><option value="baridimob">DZD BARIDIMOB</option></select></div><div class="form-field full"><label>Référence (facultatif)</label><input class="field" name="reference" maxlength="160"></div><div class="form-field full"><label>Note (facultatif)</label><input class="field" name="note" maxlength="500"></div><div class="form-field full"><button class="btn primary">Enregistrer le versement</button></div></form>'};render();}
function openVersementCheckout(){const b=basket(),sum=total();if(!b.items.length){toast('Ajoutez au moins un article avant de créer un versement.','warning');return;}if(!(sum>0)){toast('Le total de la vente est invalide.','warning');return;}const cashier=state.user?.name||state.user?.username||'';state.versementDraft={customer_name:b.customer?.name||'',phone:b.customer?.phone||'',vendor_name:cashier,amount:0,method:'cash'};state.drawer={title:'F6 · Nouveau versement',html:`<div class="versement-summary"><span>Total de la vente</span><strong>${money(sum)} DZD</strong></div><form id="versement-form" class="form-grid"><div class="form-field full"><label>Nom du client</label><input class="field" name="customer_name" maxlength="200" value="${esc(state.versementDraft.customer_name)}" required></div><div class="form-field"><label>Téléphone (facultatif)</label><input class="field" name="phone" maxlength="40" value="${esc(state.versementDraft.phone)}"></div><div class="form-field"><label>Nom du vendeur</label><input class="field" name="vendor_name" maxlength="80" value="${esc(state.versementDraft.vendor_name)}" required></div><div class="form-field"><label>Montant versé</label><input class="field" name="amount" type="number" min="0.01" step=".01" value="" required autofocus></div><div class="form-field"><label>Mode de paiement de l’avance</label><select class="field" name="method"><option value="cash">Espèces</option><option value="tpe">TPE</option><option value="baridimob">BaridiMob</option></select></div><div class="form-field full versement-remaining"><span>Reste à payer</span><strong id="versement-remaining">${money(sum)} DZD</strong></div><div class="form-field full"><button class="btn primary">Valider le versement</button></div></form><p class="muted small">Le solde sera suivi dans Versements, sans créer de crédit client.</p>`};render();}

