function addStudioObject(kind,type,x=35,y=35){const layout=kind==='label'?state.labelLayout:state.receiptLayout;if(!layout)return;const obj={id:'obj-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),type,x,y,w:70,h:10,fontSize:12,color:'#172033',background:'transparent',fontFamily:'Arial',fontWeight:400,align:'center',rotation:0,opacity:1,border:'0',visible:true};layout.elements.push(obj);const art=document.querySelector(kind==='label'?'#label-artboard':'#receipt-artboard');art?.insertAdjacentHTML('beforeend',kind==='label'?designerElement(obj):receiptDesignerElement(obj));showDesignerProps(kind,obj.id);}
